DECLARE @category varchar(24)=?,@value varchar(10)=?,@name nvarchar(24)=?,@ordering int=?,@active bit=?,@from date=?,@to date=?,@remarks nvarchar(240)=?,@actor nvarchar(128)=?,@now datetimeoffset(7)=?; DECLARE @saved TABLE(version bigint); DECLARE @version bigint=?; UPDATE dbo.m_code SET code_name=@name,display_order=@ordering,is_active=@active,valid_from=@from,valid_to=@to,remarks=@remarks,updated_at=@now,updated_by=@actor,row_version=row_version+1 OUTPUT INSERTED.row_version INTO @saved WHERE category_id=@category AND code_value=@value AND row_version=@version; SELECT version FROM @saved;
